/// This message wraps up the information written by out-of-disk detection job.
class SqlOutOfDiskReportResponse {
  /// The minimum recommended increase size in GigaBytes This field is consumed by the frontend * Writers: * the proactive database wellness job for OOD. * Readers:
  final int sqlMinRecommendedIncreaseSizeGb;

  /// This field represents the state generated by the proactive database wellness job for OutOfDisk issues. * Writers: * the proactive database wellness job for OOD. * Readers: * the proactive database wellness job
  final String sqlOutOfDiskState;

  SqlOutOfDiskReportResponse({
    required this.sqlMinRecommendedIncreaseSizeGb,
    required this.sqlOutOfDiskState,
  });

  Map<String, dynamic> toMap() {
    final map = <String, dynamic>{};
    map['sqlMinRecommendedIncreaseSizeGb'] = sqlMinRecommendedIncreaseSizeGb;
    map['sqlOutOfDiskState'] = sqlOutOfDiskState;
    return map;
  }

  factory SqlOutOfDiskReportResponse.fromMap(Map<String, dynamic> map) {
    return SqlOutOfDiskReportResponse(
      sqlMinRecommendedIncreaseSizeGb:
          map['sqlMinRecommendedIncreaseSizeGb'] as int,
      sqlOutOfDiskState: map['sqlOutOfDiskState'] as String,
    );
  }
}
